@Test
public void testLookup() throws Exception {
    PulsarClient client = PulsarClient.builder().serviceUrl("pulsar://localhost:" + proxyConfig.getServicePort()).connectionsPerBroker(5).ioThreads(5).build();
    assertTrue(proxyService.getLookupRequestSemaphore().tryAcquire());
    assertTrue(proxyService.getLookupRequestSemaphore().tryAcquire());
    Producer<byte[]> producer1 = client.newProducer().topic("persistent://sample/test/local/producer-topic").create();
    assertTrue(proxyService.getLookupRequestSemaphore().tryAcquire());
    try {
        Producer<byte[]> producer2 = client.newProducer().topic("persistent://sample/test/local/producer-topic").create();
        Assert.fail("Should have failed since can't acquire LookupRequestSemaphore");
    } catch (Exception ex) {
        // Ignore
    }
    Assert.assertEquals(LookupProxyHandler.rejectedPartitionsMetadataRequests.get(), 1.0d);
    proxyService.getLookupRequestSemaphore().release();
    try {
        Producer<byte[]> producer3 = client.newProducer().topic("persistent://sample/test/local/producer-topic").create();
    } catch (Exception ex) {
        Assert.fail("Should not have failed since can acquire LookupRequestSemaphore");
    }
    Assert.assertEquals(LookupProxyHandler.rejectedPartitionsMetadataRequests.get(), 1.0d);
    client.close();
}

