public void testLookup() throws Exception {
    PulsarClient client = PulsarClient.builder().serviceUrl("pulsar://localhost:" + proxyConfig.getServicePort()).connectionsPerBroker(5).ioThreads(5).build();
    assertTrue(proxyService.getLookupRequestSemaphore().tryAcquire());
